import{describe,it,expect,beforeEach,afterEach,vi}from"vitest";import RoutePlanner from"../../frontend/route-planner/route-planner.js";describe("Route Planner Caching",()=>{beforeEach(()=>{localStorage.clear()}),afterEach(()=>{localStorage.clear(),vi.restoreAllMocks()}),it("buildCacheKey formats correctly",()=>{const e=RoutePlanner.buildCacheKey(["delhi","agra"],"road");expect(e).toBe("iie_route_cache_v1:road:delhi>agra")}),it("readCache returns null when entry does not exist",async()=>{const e=await RoutePlanner.getRoute([{id:"delhi",lat:28.6139,lng:77.209},{id:"agra",lat:27.1767,lng:78.0081}],"rail");expect(e.fromCache).toBe(!1);const t=await RoutePlanner.getRoute([{id:"delhi",lat:28.6139,lng:77.209},{id:"agra",lat:27.1767,lng:78.0081}],"rail");expect(t.fromCache).toBe(!0)}),it("evicts cache entries older than TTL",async()=>{const e=[{id:"delhi",lat:28.6139,lng:77.209},{id:"agra",lat:27.1767,lng:78.0081}];await RoutePlanner.getRoute(e,"rail");const t=RoutePlanner.buildCacheKey(["delhi","agra"],"rail"),a=localStorage.getItem(t);expect(a).toBeTruthy();const o=JSON.parse(a);o.savedAt=Date.now()-6912e5,localStorage.setItem(t,JSON.stringify(o));const l=await RoutePlanner.getRoute(e,"rail");expect(l.fromCache).toBe(!1)}),it("enforces maximum cache entries limit of 20 using LRU policy",async()=>{const e=RoutePlanner.MAX_CACHE_ENTRIES;expect(e).toBe(20);for(let t=0;t<e;t++){const e=[{id:`stop_start_${t}`,lat:28.6,lng:77.2},{id:`stop_end_${t}`,lat:27.1,lng:78}];await RoutePlanner.getRoute(e,"rail")}let t=Object.keys(localStorage).filter(e=>e.startsWith("iie_route_cache_v1:"));expect(t.length).toBe(20);const a=await RoutePlanner.getRoute([{id:"stop_start_0",lat:28.6,lng:77.2},{id:"stop_end_0",lat:27.1,lng:78}],"rail");expect(a.fromCache).toBe(!0);await RoutePlanner.getRoute([{id:"stop_start_new",lat:28.6,lng:77.2},{id:"stop_end_new",lat:27.1,lng:78}],"rail"),t=Object.keys(localStorage).filter(e=>e.startsWith("iie_route_cache_v1:")),expect(t.length).toBe(20);const o=RoutePlanner.buildCacheKey(["stop_start_0","stop_end_0"],"rail");expect(localStorage.getItem(o)).toBeTruthy();const l=RoutePlanner.buildCacheKey(["stop_start_1","stop_end_1"],"rail");expect(localStorage.getItem(l)).toBeNull()}),it("purges all route caches when QuotaExceededError is thrown on setItem",async()=>{localStorage.setItem("theme","dark");const e=localStorage.setItem;let t=!1;vi.spyOn(Storage.prototype,"setItem").mockImplementation(function(a,o){if(t&&a.startsWith("iie_route_cache_v1:")){t=!1;const e=new Error("Mock Storage Quota Exceeded");throw e.name="QuotaExceededError",e}return e.call(this,a,o)});await RoutePlanner.getRoute([{id:"s1",lat:28,lng:77},{id:"s2",lat:27,lng:78}],"rail"),expect(Object.keys(localStorage).filter(e=>e.startsWith("iie_route_cache_v1:")).length).toBe(1),t=!0,await RoutePlanner.getRoute([{id:"s3",lat:28,lng:77},{id:"s4",lat:27,lng:78}],"rail");const a=Object.keys(localStorage).filter(e=>e.startsWith("iie_route_cache_v1:"));expect(a.length).toBe(1),expect(a[0]).toContain("s3>s4"),expect(localStorage.getItem("theme")).toBe("dark")}),it("sweepExpiredCache purges all expired keys",()=>{const e="iie_route_cache_v1:rail:active1>active2",t="iie_route_cache_v1:rail:exp1>exp2",a="theme";localStorage.setItem(e,JSON.stringify({savedAt:Date.now(),data:{}})),localStorage.setItem(t,JSON.stringify({savedAt:Date.now()-6912e5,data:{}})),localStorage.setItem(a,"light"),RoutePlanner.sweepExpiredCache(),expect(localStorage.getItem(e)).toBeTruthy(),expect(localStorage.getItem(t)).toBeNull(),expect(localStorage.getItem(a)).toBe("light")})});